from typing import Iterable
from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed
from datetime import date


def _format_day(absent_day: date) -> str:
    return (
        f"{absent_day:%B} {absent_day.day}, "
        f"{absent_day.year}"
    )


# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Parent notice listing absent days, oldest first."""
    entries = list(marks)
    others = [
        mark for mark in entries
        if mark.student_id != student.student_id
    ]
    if others:
        student_ids = sorted(
            {mark.student_id for mark in others}
        )
        raise ValueError(
            f"marks belong to other students: {student_ids}"
        )
    missed = days_missed(entries)
    if not missed:
        raise ValueError(
            f"no absences for student {student.student_id}"
        )
    count = len(missed)
    noun = "day" if count == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    listing = "\n".join(
        f"  {_format_day(absent_day)}"
        for absent_day in missed
    )
    return (
        "Dear parent or guardian,\n\n"
        f"{name} was marked absent on {count} {noun}:\n"
        f"{listing}\n"
    )
